<tr><td class="style_td">☆☆☆☆☆</td><td class="style_td" style="text-align:center;">150</td><td class="style_td" style="text-align:center;">600</td><td class="style_td" style="text-align:center;">x3</td><td class="style_td">装備スロット3の開放</td></tr>
